def scatter(ax,Y,idx,col,s=8,alpha=.7,**kwargs):return ax.scatter(*(Y[idx]*1e3).T,c=col,s=s,alpha=alpha,depthshade=False,rasterized=True,**kwargs)
def scaffold(ax):
 scatter(ax,X,np.arange(NC,N),'#a1a9b1',s=5,alpha=.23);scatter(ax,X,np.flatnonzero(~sup),'#736a9f',s=8,alpha=.4);scatter(ax,X,np.flatnonzero(sup),'#e6c185',s=11,alpha=.9)
def arrows(ax,ff,color,scale=4e4):
 # Fixed gain metres per newton; subset of original IDs, no normalized directions.
 ax.quiver(*(X[arrowids]*1e3).T,*(ff[arrowids]*scale*1e3).T,color=color,linewidth=1.3,arrow_length_ratio=.3,normalize=False,zorder=20)
